<?php
require 'config/database.php';require 'includes/auth.php';require_role('admin');
$users=(int)$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM redemptions WHERE status='pending'")->fetchColumn();$points=(int)$pdo->query("SELECT COALESCE(SUM(points),0) FROM wallet_transactions WHERE points>0")->fetchColumn();$flagged=(int)$pdo->query("SELECT COUNT(*) FROM recycling_sessions WHERE status='flagged'")->fetchColumn();
$recent=$pdo->query("SELECT s.*,u.name,m.name AS material FROM recycling_sessions s JOIN users u ON u.id=s.user_id JOIN material_categories m ON m.id=s.material_id ORDER BY s.created_at DESC LIMIT 10")->fetchAll();$pageTitle='Administrator dashboard';include 'includes/header.php';?>
<div class="dashboard-head"><div><span class="eyebrow">SYSTEM ADMINISTRATION</span><h1>EcoPoints overview</h1><p>Monitor participation, submissions, rewards, and system activity.</p></div></div>
<div class="admin-stats"><div class="metric"><span>REGISTERED USERS</span><b><?=$users?></b></div><div class="metric"><span>POINTS AWARDED</span><b><?=number_format($points)?></b></div><div class="metric"><span>PENDING CLAIMS</span><b><?=$pending?></b></div><div class="metric"><span>FLAGGED SESSIONS</span><b><?=$flagged?></b></div></div>
<div class="admin-links"><a href="admin_users.php">User management →</a><a href="admin_rewards.php">Rewards & inventory →</a><a href="admin_review.php">Submission review →</a></div>
<section class="panel"><div class="panel-title"><h2>Recent recycling sessions</h2></div><?php if(!$recent):?><div class="empty-state">No recycling sessions recorded.</div><?php else:foreach($recent as $s):?><div class="claim-row"><div><b><?=htmlspecialchars($s['material'])?> · <?=htmlspecialchars($s['student_name'])?></b><small><?=htmlspecialchars($s['created_at'])?> · <?=htmlspecialchars($s['station_id'])?></small></div><span class="status <?=htmlspecialchars($s['status'])?>"><?=htmlspecialchars($s['status'])?></span></div><?php endforeach;endif;?></section>
